import pyomo.environ as pyo

DATA = {
    "warehouses": [1, 2, 3, 4, 5, 6, 7],
    "initial": {
        1: 57, 2: 180, 3: 288, 4: 255, 5: 477, 6: 222, 7: 314,
    },
    "required": {
        1: 499, 2: 173, 3: 293, 4: 158, 5: 15, 6: 78, 7: 278,
    },
    # cost[i][j] = cost to move one unit from warehouse i to warehouse j
    "cost": {
        1: {2: 36, 3: 36, 4: 48, 5: 10, 6: 20, 7: 48},
        2: {1: 28, 3: 16, 4: 18, 5: 36, 6: 42, 7: 12},
        3: {1: 6, 2: 40, 4: 49, 5: 31, 6: 1, 7: 46},
        4: {1: 14, 2: 22, 3: 4, 5: 9, 6: 12, 7: 1},
        5: {1: 50, 2: 44, 3: 7, 4: 48, 6: 7, 7: 25},
        6: {1: 26, 2: 9, 3: 33, 4: 38, 5: 8, 7: 30},
        7: {1: 8, 2: 9, 3: 2, 4: 13, 5: 8, 6: 49},
    },
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    whs = d["warehouses"]

    model = pyo.ConcreteModel()

    model.WH = pyo.Set(initialize=whs, ordered=True)

    # pairs (i, j) with i != j
    model.ARC = pyo.Set(
        initialize=[(i, j) for i in whs for j in whs if i != j],
        dimen=2,
    )

    model.ship = pyo.Var(model.ARC, within=pyo.NonNegativeReals)

    def obj_rule(m):
        return sum(d["cost"][i][j] * m.ship[i, j] for (i, j) in m.ARC)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Final balance: initial + inflow - outflow == required
    def balance_rule(m, k):
        inflow = sum(m.ship[i, k] for i in whs if i != k)
        outflow = sum(m.ship[k, j] for j in whs if j != k)
        return d["initial"][k] + inflow - outflow == d["required"][k]

    model.balance = pyo.Constraint(model.WH, rule=balance_rule)

    return model
